#!/usr/bin/env bash
# Remove the files generated by building, testing and documenting pymsz.
# Only the paths listed below are deleted: never source files, test data, .venv or git itself.
#
# usage: ./clean.sh           build products, caches, documentation build, example outputs
#        ./clean.sh --all     also the compiled SZpack extension, the local GSL (third_party/) and
#                             pymsz/version.py; rebuild them with  pip install -e .  (or ./build_szpack.sh)
#        ./clean.sh -n        only print what would be removed (also: ./clean.sh --all -n)
set -euo pipefail
cd "$(dirname "$0")"

ALL=0
DRY=0
for a in "$@"; do
    case "$a" in
        --all) ALL=1 ;;
        -n|--dry-run) DRY=1 ;;
        -h|--help) sed -n '2,8p' "$0"; exit 0 ;;
        *) echo "clean.sh: unknown option $a (see ./clean.sh --help)" >&2; exit 1 ;;
    esac
done

remove() {  # delete the given paths that exist
    for p in "$@"; do
        [ -e "$p" ] || [ -L "$p" ] || continue
        echo "remove $p"
        [ "$DRY" -eq 1 ] || rm -rf -- "$p"
    done
}

# packaging: pip install / python -m build
remove build dist .eggs ./*.egg-info

# Python bytecode, pytest/ruff caches, Jupyter checkpoints (not inside .venv, .git, SZpack, third_party)
while IFS= read -r -d '' p; do
    remove "$p"
done < <(find . \( -path ./.venv -o -path ./.git -o -path ./SZpack -o -path ./third_party \) -prune -o \
              \( -type d \( -name __pycache__ -o -name .pytest_cache -o -name .ipynb_checkpoints \) -prune -print0 \) -o \
              \( -type f -name '*.pyc' -print0 \))
remove .ruff_cache

# documentation build (make -C docs html)
remove docs/_build docs/api/generated docs/reference/_generated

# outputs of the example run: pymsz-mock test/mock_CL288.yaml
remove test/mock_CL288

if [ "$ALL" -eq 1 ]; then
    remove pymsz/szpack/SZpack.*.so pymsz/szpack/SZpack.*.pyd   # compiled SZpack extension
    remove third_party                                         # GSL from ./build_szpack.sh --build-gsl
    remove pymsz/version.py                                    # written by setup.py
fi
